import{_ as a,c as o,o as n,j as r,Y as i,t as s}from"./chunks/framework.D-NV0Bun.js";const f=JSON.parse('{"title":"timeout | x-cmd man (man1) | run a command with a time limit","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | timeout - run a command with a time limit","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"timeout | x-cmd man (man1) | run a command with a time limit"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | timeout - run a command with a time limit"}]]},"headers":[],"params":{"isMan":true,"man":"timeout","category":"man1","desc":"run a command with a time limit"},"relativePath":"man1/timeout.md","filePath":"man1/[man].md"}'),l={name:"man1/timeout.md"},d={class:"visually-hidden"};function m(e,t,u,h,p,c){return n(),o("div",null,[r("h1",d,s(e.$params.man),1),t[0]||(t[0]=i('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>timeout - run a command with a time limit</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>timeout</strong> [<em>OPTION</em>] *DURATION COMMAND *[<em>ARG</em>]... <br> <strong>timeout</strong> [<em>OPTION</em>]</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Start COMMAND, and kill it if still running after DURATION.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><p><strong>--preserve-status</strong></p><blockquote><p>exit with the same status as COMMAND, even when the</p></blockquote><blockquote><p>command times out</p></blockquote><p><strong>--foreground</strong></p><blockquote><p>when not running timeout directly from a shell prompt,</p></blockquote><blockquote><p>allow COMMAND to read from the TTY and get TTY signals; in this mode, children of COMMAND will not be timed out</p></blockquote><p><strong>-k</strong>, <strong>--kill-after</strong>=<em>DURATION</em></p><blockquote><p>also send a KILL signal if COMMAND is still running</p></blockquote><blockquote><p>this long after the initial signal was sent</p></blockquote><p><strong>-s</strong>, <strong>--signal</strong>=<em>SIGNAL</em></p><blockquote><p>specify the signal to be sent on timeout;</p></blockquote><blockquote><p>SIGNAL may be a name like &#39;HUP&#39; or a number; see &#39;kill <strong>-l</strong>&#39; for a list of signals</p></blockquote><dl><dt><strong>-v</strong>, <strong>--verbose</strong></dt><dd>diagnose to stderr any signal sent upon timeout</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>DURATION is a floating point number with an optional suffix: &#39;s&#39; for seconds (the default), &#39;m&#39; for minutes, &#39;h&#39; for hours or &#39;d&#39; for days. A duration of 0 disables the associated timeout.</p><p>Upon timeout, send the TERM signal to COMMAND, if no other SIGNAL specified. The TERM signal kills any process that does not block or catch that signal. It may be necessary to use the KILL signal, since this signal can&#39;t be caught.</p><h3 id="exit-status" tabindex="-1">Exit status: <a class="header-anchor" href="#exit-status" aria-label="Permalink to &quot;Exit status:&quot;">​</a></h3><dl><dt>124</dt><dd>if COMMAND times out, and <strong>--preserve-status</strong> is not specified</dd><dt>125</dt><dd>if the timeout command itself fails</dd><dt>126</dt><dd>if COMMAND is found but cannot be invoked</dd><dt>127</dt><dd>if COMMAND cannot be found</dd><dt>137</dt><dd>if COMMAND (or timeout itself) is sent the KILL (9) signal (128+9)</dd><dt>-</dt><dd>the exit status of COMMAND otherwise</dd></dl><h2 id="bugs" tabindex="-1">BUGS <a class="header-anchor" href="#bugs" aria-label="Permalink to &quot;BUGS&quot;">​</a></h2><p>Some platforms don&#39;t currently support timeouts beyond the year 2038.</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Padraig Brady.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>kill</strong>(1)</p><p><br> Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/timeout%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/timeout\\</a>&gt; <br> or available locally via: info &#39;(coreutils) timeout invocation&#39;</p>',35))])}const b=a(l,[["render",m]]);export{f as __pageData,b as default};
